file.contenuto:
extends Control

var count: int = 0

@onready var count_label: Label = $CountLabel
@onready var add_button: Button = $AddButton


func _ready() -> void:
	add_button.pressed.connect(_on_add_button_pressed)


func _on_add_button_pressed() -> void:
	count += 1
	count_label.text = str(count)
